def transform(grid):
    starts = (0, 5, 10, 15)
    colors = (8, 5, 9, 4)
    priority = (9, 4, 8, 5)
    out = []
    for r in range(4):
        row = []
        for c in range(4):
            present = {colors[k] for k, start in enumerate(starts) if grid[r][start+c] == colors[k]}
            row.append(next((color for color in priority if color in present), 0))
        out.append(row)
    return out
